(7275341, 1132920, 113411, '<td valign="top">really nice!</td>', 'really nice!', '2014-10-20 01:38:52.000000', NULL, 1),
(7275395, 1132737, 117534, '<td valign="top">OMG Borzois I LOVE them! Had one named Rastus who looked just like the dog closest to me. 10 for not only a real good picture but tugging my heart strings</td>', 'OMG Borzois I LOVE them! Had one named Rastus who looked just like the dog closest to me. 10 for not only a real good picture but tugging my heart strings', '2014-10-20 09:24:12.000000', NULL, 1),
(7275397, 1133010, 63218, '<td valign="top">This is almost perfect. The black line on the right border looks like the result of careless cropping. Otherwise, the arrangement of tones, shapes, &amp; lines is interesting to look at.</td>', 'This is almost perfect. The black line on the right border looks like the result of careless cropping. Otherwise, the arrangement of tones, shapes, & lines is interesting to look at.', '2014-10-20 09:43:29.000000', NULL, 1),
(7275399, 1132833, 63218, '<td valign="top">Oh, well done! Food for my imagination. Thanks!</td>', 'Oh, well done! Food for my imagination. Thanks!', '2014-10-20 09:47:27.000000', NULL, 1),
(7275404, 1132983, 113411, '<td valign="top">I think this is the reverse of Shallow Depth of Field. The blur is great but there is nothing in the foreground in<br/>focus.</td>', 'I think this is the reverse of Shallow Depth of Field. The blur is great but there is nothing in the foreground infocus.', '2014-10-20 10:24:02.000000', NULL, 1),
(7275405, 1132833, 113411, '<td valign="top">Really interesting abstract. I am not getting Depth of Field.</td>', 'Really interesting abstract. I am not getting Depth of Field.', '2014-10-20 10:26:05.000000', NULL, 1),
(7275406, 1133010, 113411, '<td valign="top">I love this !!!!</td>', 'I love this !!!!', '2014-10-20 10:28:48.000000', NULL, 1),
