(7275420, 1132425, 37392, '<td valign="top"><strike></strike></td>', '', '2014-10-20 11:21:49.000000', NULL, 1),
(7275436, 1132878, 61552, '<td valign="top">I know the rule of thirds, and I know it''s better for the subject to be entering the scene rather than leaving it.  The close-up macro of the fly is excellent, I''m hoping to do as well with my new lenses on order. I personally think this is exaggerated, meaning too far from that vertical third line.  I could be wrong, I interpret the rule of thirds as the place to center the subject, and it looks like you''ve placed your subject completely within the top-right third box. I still give this a 6 for clarity, detail, and deep rich colors.</td>', 'I know the rule of thirds, and I know it''s better for the subject to be entering the scene rather than leaving it.  The close-up macro of the fly is excellent, I''m hoping to do as well with my new lenses on order. I personally think this is exaggerated, meaning too far from that vertical third line.  I could be wrong, I interpret the rule of thirds as the place to center the subject, and it looks like you''ve placed your subject completely within the top-right third box. I still give this a 6 for clarity, detail, and deep rich colors.', '2014-10-20 12:38:53.000000', NULL, 1),
(7275437, 1132919, 61552, '<td valign="top">There''s an emotional tug on this one.</td>', 'There''s an emotional tug on this one.', '2014-10-20 12:41:53.000000', NULL, 1),
(7275442, 1132906, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2014-10-20 12:58:34.000000', NULL, 1),
