(7275593, 1132697, 113411, '<td valign="top">I''m in love! What a face.....</td>', 'I''m in love! What a face.....', '2014-10-21 09:53:02.000000', NULL, 1),
(7275594, 1132831, 113411, '<td valign="top">Wonderful piece of art!</td>', 'Wonderful piece of art!', '2014-10-21 09:53:47.000000', NULL, 1),
(7275595, 1132922, 113411, '<td valign="top">great colors and composition!</td>', 'great colors and composition!', '2014-10-21 09:54:13.000000', NULL, 1),
(7275596, 1132874, 113411, '<td valign="top">fabulous!</td>', 'fabulous!', '2014-10-21 09:54:30.000000', NULL, 1),
(7275607, 1132846, 114225, '<td valign="top">I really adore the light and color.</td>', 'I really adore the light and color.', '2014-10-21 11:54:08.000000', NULL, 1),
(7275634, 1132846, 60173, '<td valign="top">The lighting is really nice, but it doesn''t have the impact it seems like it should. Perhaps a square crop would have been better?</td>', 'The lighting is really nice, but it doesn''t have the impact it seems like it should. Perhaps a square crop would have been better?', '2014-10-21 13:28:54.000000', NULL, 1),
(7275635, 1132962, 60173, '<td valign="top">Not a big fan of the pose, but I like everything else about it.</td>', 'Not a big fan of the pose, but I like everything else about it.', '2014-10-21 13:29:22.000000', NULL, 1),
(7275742, 1132882, 170281, '<td valign="top">Nice color and framing.</td>', 'Nice color and framing.', '2014-10-21 21:26:30.000000', NULL, 1),
(7275746, 1132960, 170281, '<td valign="top">Nice image.  It looks as though the Mantis was posing for the shot.</td>', 'Nice image.  It looks as though the Mantis was posing for the shot.', '2014-10-21 21:34:07.000000', NULL, 1),
(7275749, 1132920, 170281, '<td valign="top">Nice!  I love the simplicity of the subject matter and capturing the shallow depth of field part way down the fence line.</td>', 'Nice!  I love the simplicity of the subject matter and capturing the shallow depth of field part way down the fence line.', '2014-10-21 21:42:07.000000', NULL, 1),
(7275787, 1132994, 170281, '<td valign="top">I love it!  The framing and use of black and white are terrific.</td>', 'I love it!  The framing and use of black and white are terrific.', '2014-10-21 22:15:33.000000', NULL, 1),
(7275797, 1132962, 170281, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2014-10-21 22:22:39.000000', NULL, 1),
(7275820, 1133007, 170281, '<td valign="top">Very cool!</td>', 'Very cool!', '2014-10-21 22:29:54.000000', NULL, 1),
(7275855, 1132959, 177322, '<td valign="top">Exquisite.</td>', 'Exquisite.', '2014-10-21 23:00:23.000000', NULL, 1),
(7275886, 1133002, 114285, '<td valign="top">Outstanding!!!</td>', 'Outstanding!!!', '2014-10-22 00:11:24.000000', NULL, 1),
(7275889, 1132958, 114285, '<td valign="top">Incredible photo!<br/> <br/>The crop is amazing, well done.</td>', 'Incredible photo! The crop is amazing, well done.', '2014-10-22 00:13:04.000000', NULL, 1),
(7275890, 1132938, 114285, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2014-10-22 00:14:07.000000', NULL, 1),
(7275891, 1132892, 114285, '<td valign="top">Splendid work!</td>', 'Splendid work!', '2014-10-22 00:14:47.000000', NULL, 1),
(7275892, 1132994, 114285, '<td valign="top">A thought provoking image.</td>', 'A thought provoking image.', '2014-10-22 00:15:45.000000', NULL, 1),
(7275894, 1132752, 114285, '<td valign="top">Gorgeous softness!</td>', 'Gorgeous softness!', '2014-10-22 00:16:12.000000', NULL, 1),
(7275896, 1132697, 114285, '<td valign="top">and a most outstanding portrait, possibly one of the best I''ve seen on here, or right up there, the crop, the look on the dog, the tones, just wonderful! 10</td>', 'and a most outstanding portrait, possibly one of the best I''ve seen on here, or right up there, the crop, the look on the dog, the tones, just wonderful! 10', '2014-10-22 00:18:01.000000', NULL, 1),
(7276024, 1132990, 107740, '<td valign="top">Beautifully captured and processed!</td>', 'Beautifully captured and processed!', '2014-10-22 09:15:17.000000', NULL, 1),
(7276039, 1132878, 153814, '<td valign="top">And I''ll see you near the top in the end.<br/>Great image, well done.</td>', 'And I''ll see you near the top in the end.Great image, well done.', '2014-10-22 10:05:37.000000', NULL, 1),
(7276040, 1132960, 153814, '<td valign="top">Puppy dog eyes from a praying mantis, ya don''t see tht every day.<br/>Well done. For an image that calls to be crisp the softness really works well on this.</td>', 'Puppy dog eyes from a praying mantis, ya don''t see tht every day.Well done. For an image that calls to be crisp the softness really works well on this.', '2014-10-22 10:07:42.000000', NULL, 1),
(7276041, 1132544, 153814, '<td valign="top">WOW!!! Tack sharp great shot.</td>', 'WOW!!! Tack sharp great shot.', '2014-10-22 10:10:01.000000', NULL, 1),
(7276158, 1132766, 13077, '<td valign="top">I like the composition and the background is pleasant and colorful. Since the challenge is shallow DOF, I don''t mind that the front of the flower is not in focus (more in the spirit of the challenge this way) but ordinarily I think it would look better if it was.</td>', 'I like the composition and the background is pleasant and colorful. Since the challenge is shallow DOF, I don''t mind that the front of the flower is not in focus (more in the spirit of the challenge this way) but ordinarily I think it would look better if it was.', '2014-10-22 14:15:29.000000', NULL, 1),
(7276163, 1133000, 13077, '<td valign="top">I like the way the background is composed and the way the shapes interact with each other. The in-focus subject is interesting as well, but it seems slightly soft.</td>', 'I like the way the background is composed and the way the shapes interact with each other. The in-focus subject is interesting as well, but it seems slightly soft.', '2014-10-22 14:19:00.000000', NULL, 1),
(7276168, 1132912, 13077, '<td valign="top">Good depth of field and subject isolation,  but the deer doesn''t take up much space in the frame and it''s pretty much dead-center without any interesting elements in the foreground or sky - not sure how much more you could have cropped without losing detail?</td>', 'Good depth of field and subject isolation,  but the deer doesn''t take up much space in the frame and it''s pretty much dead-center without any interesting elements in the foreground or sky - not sure how much more you could have cropped without losing detail?', '2014-10-22 14:30:44.000000', NULL, 1),
(7276170, 1132752, 13077, '<td valign="top">That''s a hairy blossom!</td>', 'That''s a hairy blossom!', '2014-10-22 14:31:35.000000', NULL, 1),
(7276171, 1132961, 13077, '<td valign="top">I like this point of view and the use of negative space, also well lit and exposed. Very graphic and striking, and meets the challenge well too.</td>', 'I like this point of view and the use of negative space, also well lit and exposed. Very graphic and striking, and meets the challenge well too.', '2014-10-22 14:32:35.000000', NULL, 1),
(7276174, 1132844, 13077, '<td valign="top">Overall it''s well done and meets the challenge, though even where the focus obviously is there''s some softness, maybe motion blur?<br/>I spent a long time looking at it trying to figure out if it''s really checkmate or not, it''s been so long since I played chess.</td>', 'Overall it''s well done and meets the challenge, though even where the focus obviously is there''s some softness, maybe motion blur?I spent a long time looking at it trying to figure out if it''s really checkmate or not, it''s been so long since I played chess.', '2014-10-22 14:40:37.000000', NULL, 1),
(7276178, 1133005, 13077, '<td valign="top">The background is pleasant but the in-focus area is a bit soft, if it''s not quite in-focus or it''s motion blur I''m not sure.</td>', 'The background is pleasant but the in-focus area is a bit soft, if it''s not quite in-focus or it''s motion blur I''m not sure.', '2014-10-22 15:02:30.000000', NULL, 1),
(7276182, 1132920, 13077, '<td valign="top">I always like the look of barbed wire from this angle, with this DOF. Nicely done.</td>', 'I always like the look of barbed wire from this angle, with this DOF. Nicely done.', '2014-10-22 15:23:59.000000', NULL, 1),
(7276183, 1132892, 13077, '<td valign="top">Beautifully dark and moody, and fascinating composition. I think I might like it even more if the top left corner was completely dark instead of having that object up there, but it''s a nitpick. Well done.</td>', 'Beautifully dark and moody, and fascinating composition. I think I might like it even more if the top left corner was completely dark instead of having that object up there, but it''s a nitpick. Well done.', '2014-10-22 15:25:00.000000', NULL, 1),
(7276184, 1132876, 13077, '<td valign="top">Very creepy and surreal. I like it.</td>', 'Very creepy and surreal. I like it.', '2014-10-22 15:25:39.000000', NULL, 1),
(7276185, 1132721, 13077, '<td valign="top">Nicely composed and good soft light, and it looks as though she''s in focus, but a bit more sharpening might have looked good. Still a nice portrait.</td>', 'Nicely composed and good soft light, and it looks as though she''s in focus, but a bit more sharpening might have looked good. Still a nice portrait.', '2014-10-22 15:26:48.000000', NULL, 1),
(7276186, 1132962, 13077, '<td valign="top">I like the soft overall feel including the lightly saturated tones, and the DOF is very shallow so it meets the challenge well.<br/>It''s an unusual pose, though. The way her hands hug both sides of her face looks fascinating when I block the rest of the photo with something, I wonder how a tight crop of that would have looked?</td>', 'I like the soft overall feel including the lightly saturated tones, and the DOF is very shallow so it meets the challenge well.It''s an unusual pose, though. The way her hands hug both sides of her face looks fascinating when I block the rest of the photo with something, I wonder how a tight crop of that would have looked?', '2014-10-22 15:30:05.000000', NULL, 1),
(7276187, 1132687, 13077, '<td valign="top">I think the centered composition works well since you''ve filled the frame with the web. The light looks good, and the details of the spider are good and sharp.</td>', 'I think the centered composition works well since you''ve filled the frame with the web. The light looks good, and the details of the spider are good and sharp.', '2014-10-22 15:31:34.000000', NULL, 1),
(7276188, 1132822, 13077, '<td valign="top">This is outstanding! I love the composition and colors, and the focus is perfectly placed and tack sharp. This is my top pick so far.</td>', 'This is outstanding! I love the composition and colors, and the focus is perfectly placed and tack sharp. This is my top pick so far.', '2014-10-22 15:33:21.000000', NULL, 1),
(7276189, 1132981, 13077, '<td valign="top">Very nice. Well placed focus and well chosen background, and excellent tones and composition.</td>', 'Very nice. Well placed focus and well chosen background, and excellent tones and composition.', '2014-10-22 15:34:05.000000', NULL, 1),
(7276190, 1133010, 13077, '<td valign="top">I really like this - good high-key look and the overall sense of chaos suits the subject well, and the compostion is very good.</td>', 'I really like this - good high-key look and the overall sense of chaos suits the subject well, and the compostion is very good.', '2014-10-22 15:34:54.000000', NULL, 1),
(7276192, 1132992, 13077, '<td valign="top">Good pen - I use those at work all the time. Just black ones though. I like the way you''ve presented the rainbow of colored pens with the marker at a diagonal angle to break up the pattern, but the reflections and surface dirt on the package of pens is a bit distracting.</td>', 'Good pen - I use those at work all the time. Just black ones though. I like the way you''ve presented the rainbow of colored pens with the marker at a diagonal angle to break up the pattern, but the reflections and surface dirt on the package of pens is a bit distracting.', '2014-10-22 15:36:57.000000', NULL, 1),
(7276193, 1132911, 13077, '<td valign="top">Good detail shot here. I like the various textures and the contrasty light/shadows.</td>', 'Good detail shot here. I like the various textures and the contrasty light/shadows.', '2014-10-22 15:37:45.000000', NULL, 1),
(7276205, 1132886, 13077, '<td valign="top">Never seen such a big cluster of them, that''s pretty cool.</td>', 'Never seen such a big cluster of them, that''s pretty cool.', '2014-10-22 16:24:10.000000', NULL, 1),
(7276207, 1132874, 13077, '<td valign="top">Wow, super cool. Great job nailing the focus and composition too.</td>', 'Wow, super cool. Great job nailing the focus and composition too.', '2014-10-22 16:24:40.000000', NULL, 1),
(7276208, 1132898, 13077, '<td valign="top">Very nice. I like the lens flare, it brings some funkiness into this peaceful autumn scene.</td>', 'Very nice. I like the lens flare, it brings some funkiness into this peaceful autumn scene.', '2014-10-22 16:25:16.000000', NULL, 1),
(7276209, 1132938, 13077, '<td valign="top">I like the simplicity and the leading lines work well.</td>', 'I like the simplicity and the leading lines work well.', '2014-10-22 16:25:39.000000', NULL, 1),
(7276213, 1132763, 13077, '<td valign="top">I like the selective desat on this one. Not sure how much tighter of a crop you could have done without losing detail, but I don''t feel like all the smooth background and the rest of the stalk of the flower are adding much.</td>', 'I like the selective desat on this one. Not sure how much tighter of a crop you could have done without losing detail, but I don''t feel like all the smooth background and the rest of the stalk of the flower are adding much.', '2014-10-22 16:29:14.000000', NULL, 1),
(7276215, 1132879, 13077, '<td valign="top">I like the backlighting and the contrast, as well as the various angles. Works well all together.</td>', 'I like the backlighting and the contrast, as well as the various angles. Works well all together.', '2014-10-22 16:29:49.000000', NULL, 1),
(7276218, 1132729, 13077, '<td valign="top">A handsome bird, nicely composed and good smooth background. I think maybe a layer of brightness and contrast with a mask to brighten and make the lighter feathers pop more might have helped though.</td>', 'A handsome bird, nicely composed and good smooth background. I think maybe a layer of brightness and contrast with a mask to brighten and make the lighter feathers pop more might have helped though.', '2014-10-22 16:32:10.000000', NULL, 1),
(7276219, 1132730, 13077, '<td valign="top">Fairly shallow, but not quite shallow enough to remove the distracting background here. Changing the angle you shot it from may have helped with that, though.</td>', 'Fairly shallow, but not quite shallow enough to remove the distracting background here. Changing the angle you shot it from may have helped with that, though.', '2014-10-22 16:32:59.000000', NULL, 1),
(7276220, 1132960, 13077, '<td valign="top">Excellent focus placement, and I like the warm, bright tones overall.</td>', 'Excellent focus placement, and I like the warm, bright tones overall.', '2014-10-22 16:33:41.000000', NULL, 1),
(7276221, 1132846, 13077, '<td valign="top">Very nice light here, and I like the soft overall look although it manages to keep just enough detail in the leaf, probably helped by the light at the edge.</td>', 'Very nice light here, and I like the soft overall look although it manages to keep just enough detail in the leaf, probably helped by the light at the edge.', '2014-10-22 16:34:28.000000', NULL, 1),
(7276223, 1132922, 13077, '<td valign="top">I like the warm color scheme here, and the leaves are very sharp while the background is pleasant and just out-of-focus enough.</td>', 'I like the warm color scheme here, and the leaves are very sharp while the background is pleasant and just out-of-focus enough.', '2014-10-22 16:36:41.000000', NULL, 1),
(7276224, 1132880, 13077, '<td valign="top">An interesting arrangement, looks attractive when I stare at the center and let my eyes drift out of focus.</td>', 'An interesting arrangement, looks attractive when I stare at the center and let my eyes drift out of focus.', '2014-10-22 16:40:35.000000', NULL, 1),
(7276225, 1132697, 13077, '<td valign="top">A very handsome dog, and excellent portrait of him/her.</td>', 'A very handsome dog, and excellent portrait of him/her.', '2014-10-22 16:41:13.000000', NULL, 1),
(7276226, 1132965, 13077, '<td valign="top">Well lit to bring out the detail in the shoe, and I like the processing and tones you''ve given it.</td>', 'Well lit to bring out the detail in the shoe, and I like the processing and tones you''ve given it.', '2014-10-22 16:43:50.000000', NULL, 1),
(7276227, 1132889, 13077, '<td valign="top">Very interesting view of old pipes. Well composed and lit, and nicely placed focus.</td>', 'Very interesting view of old pipes. Well composed and lit, and nicely placed focus.', '2014-10-22 16:44:23.000000', NULL, 1),
(7276228, 1132953, 13077, '<td valign="top">Good colors and light, well placed focus too.</td>', 'Good colors and light, well placed focus too.', '2014-10-22 16:45:42.000000', NULL, 1),
(7276229, 1132930, 13077, '<td valign="top">I like it. Simple, attractive and meets the challenge well.</td>', 'I like it. Simple, attractive and meets the challenge well.', '2014-10-22 16:46:19.000000', NULL, 1),
(7276230, 1132641, 13077, '<td valign="top">Very colorful and well composed, nicely done.</td>', 'Very colorful and well composed, nicely done.', '2014-10-22 16:46:49.000000', NULL, 1),
(7276231, 1132677, 13077, '<td valign="top">Cool angle, an bug''s-eye view of a scene full of dangers and huge things.</td>', 'Cool angle, an bug''s-eye view of a scene full of dangers and huge things.', '2014-10-22 16:47:59.000000', NULL, 1),
(7276234, 1132958, 13077, '<td valign="top">I like the low-key sort of feel here.</td>', 'I like the low-key sort of feel here.', '2014-10-22 16:57:45.000000', NULL, 1),
(7276236, 1132933, 13077, '<td valign="top">Are they real people or action figures? With the processing I can''t really tell...</td>', 'Are they real people or action figures? With the processing I can''t really tell...', '2014-10-22 16:58:43.000000', NULL, 1),
(7276237, 1132628, 13077, '<td valign="top">They sure are funny looking. But tasty.</td>', 'They sure are funny looking. But tasty.', '2014-10-22 16:59:11.000000', NULL, 1),
(7276238, 1132425, 13077, '<td valign="top">This is very attractive as a whole. The background is like an abstract painting, and the shallow DOF makes the grate fascinating.</td>', 'This is very attractive as a whole. The background is like an abstract painting, and the shallow DOF makes the grate fascinating.', '2014-10-22 17:00:22.000000', NULL, 1),
(7276239, 1132983, 13077, '<td valign="top">The lo-fi approach works very well here, and I''m interested to check back and see the technique you''ve used.</td>', 'The lo-fi approach works very well here, and I''m interested to check back and see the technique you''ve used.', '2014-10-22 17:01:41.000000', NULL, 1),
(7276333, 1132981, 114285, '<td valign="top">Incredibly beautiful. Looks like an Ursula!</td>', 'Incredibly beautiful. Looks like an Ursula!', '2014-10-23 02:21:58.000000', NULL, 1),
