(7276430, 1133002, 65234, '<td valign="top">Interesting image (in a good way).  Debating whether I would have reduced the background noise and make this even more dreamy.</td>', 'Interesting image (in a good way).  Debating whether I would have reduced the background noise and make this even more dreamy.', '2014-10-23 09:57:22.000000', NULL, 1),
(7276431, 1132743, 65234, '<td valign="top">Lovely detail and nice use of DOF.  Love the catchlight in that big, beautiful eye.</td>', 'Lovely detail and nice use of DOF.  Love the catchlight in that big, beautiful eye.', '2014-10-23 09:58:02.000000', NULL, 1),
(7276432, 1132589, 65234, '<td valign="top">Slow and steady wins the race and all that ;-)  To him, that view must be like looking over a cliff!  Love the shapes and textures here.</td>', 'Slow and steady wins the race and all that ;-)  To him, that view must be like looking over a cliff!  Love the shapes and textures here.', '2014-10-23 09:59:08.000000', NULL, 1),
